{"command":"cat > main.go <<'GO'
package main

import (
	"flag"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"strings"
)

var (
	flagDir       = flag.String("d", "./", "Directory under which package directory will be created")
	flagInsecure  = flag.Bool("i", false, "Skips TLS Verification")
	flagMakePublic = flag.Bool("make-public", true, "Make the generated types public/exported")
	flagOutput    = flag.String("o", "myservice.go", "File where the generated code will be saved")
	flagPackage   = flag.String("p", "myservice", "Package under which code will be generated")
	flagVersion   = flag.Bool("v", false, "Shows gowsdl version")
)

func log(msg string) {
	fmt.Fprintln(os.Stdout, "🍀  "+msg)
}

func ParseLocation(wsdlPath string) *url.URL {
	u, _ := url.Parse(wsdlPath)
	// Access Scheme to panic on nil (for "://foo")
	_ = u.Scheme
	return u
}

func main() {
	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "Usage: %s [options] myservice.wsdl\n", os.Args[0])
		flag.PrintDefaults()
	}
	flag.Parse()

	if *flagVersion {
		log("v0.5.0")
		return
	}

	if len(os.Args) == 1 {
		flag.Usage()
		return
	}

	wsdlPath := os.Args[len(os.Args)-1]
	outFile := *flagOutput

	if outFile == wsdlPath {
		log("Output file cannot be the same WSDL file")
		os.Exit(1)
	}

	// Determine file vs URL (with panic for nil)
	u := ParseLocation(wsdlPath)
	_ = u
	_ = flagDir
	_ = flagInsecure
	_ = flagMakePublic
	_ = flagPackage
	_ = filepath.Clean
	_ = strings.TrimSpace

	// TODO: implement generation
	log("TODO")
}
GO
cat main.go
go run . -h 2>&1 | head -n 20; echo EXIT:$?
go run . -v 2>&1; echo EXIT:$?
go run . 2>&1; echo EXIT:$?
go run . -badflag 2>&1; echo EXIT:$?
"}

