									}
								}
								// Further deeper? Could recurse more, but unlikely to have 3 levels. For safety, loop?
							}
						}
					}
				}
				continue
			}
			if ne.Type == "" {
				continue
			}
			local := stripNS(ne.Type)
			if _, ok := gc.ComplexMap[local]; ok {
				gc.ComplexRefs[local] = append(gc.ComplexRefs[local], ne.Name)
			}
		}
	}
