func getComplexNestedElements(ct *ComplexType) []Element {
	var elems []Element
	if ct == nil {
		return elems
	}
	// If simpleContent or complexContent with extension? For complexContent extension, nested are in extension's sequence/choice/all
	// For simpleContent, no nested elements (only Value + attributes). So ignore.
	if ct.ComplexContent != nil && ct.ComplexContent.Extension != nil {
		ext := ct.ComplexContent.Extension
		if ext.Sequence != nil {
			elems = append(elems, ext.Sequence.Elements...)
			for _, ch := range ext.Sequence.Choices {
				elems = append(elems, ch.Elements...)
			}
			// Ignore Sequences inside Sequence, Groups, Anys (Anys not referencing complex)
		}
		if ext.Choice != nil {
			elems = append(elems, ext.Choice.Elements...)
		}
		if ext.All != nil {
			elems = append(elems, ext.All.Elements...)
		}
		// Note: Extension's base is not a nested element, it's embedding. Ignore for refs? The base complex is referenced via embedding, not via element name. Should it count for XMLName? For VersionInfo extending BaseResponse, does BaseResponse get XMLName from VersionInfo? No, BaseResponse has no XMLName. So embedding doesn't count. Good.
		return elems
	}
	if ct.SimpleContent != nil {
		return elems
	}
	// Normal: sequence/choice/all
	if ct.Sequence != nil {
		elems = append(elems, ct.Sequence.Elements...)
		for _, ch := range ct.Sequence.Choices {
			elems = append(elems, ch.Elements...)
		}
	}
	if ct.Choice != nil {
		elems = append(elems, ct.Choice.Elements...)
	}
	if ct.All != nil {
		elems = append(elems, ct.All.Elements...)
	}
	return elems
}

