		TargetNSMap: make(map[string]string),
		ElementsMap: make(map[string]*ElementInfo),
		ComplexMap: make(map[string]*ComplexInfo),
		SimpleMap: make(map[string]*SimpleInfo),
		AttrMap: make(map[string]*AttrInfo),
		ComplexRefs: make(map[string][]string),
	}
