		return elems
	}
	if ct.SimpleContent != nil {
		return elems
	}
	// Normal: sequence/choice/all
	if ct.Sequence != nil {
		elems = append(elems, ct.Sequence.Elements...)
		for _, ch := range ct.Sequence.Choices {
			elems = append(elems, ch.Elements...)
		}
	}
	if ct.Choice != nil {
		elems = append(elems, ct.Choice.Elements...)
	}
	if ct.All != nil {
		elems = append(elems, ct.All.Elements...)
	}
	return elems
}

