func resolveMessageGoType(opMsg *OperationMessage, msgMap map[string]*Message) string {
	if opMsg == nil || opMsg.Message == "" {
		return "EmptyString"
	}
	msgLocal := stripNS(opMsg.Message)
	msg, ok := msgMap[msgLocal]
	if !ok || len(msg.Parts) == 0 {
		return "EmptyString"
	}
	part := msg.Parts[0]
	if part.Element != "" {
		elemLocal := stripNS(part.Element)
		return makePublicName(elemLocal, true)
	}
	if part.Type != "" {
		typeLocal := stripNS(part.Type)
		knownPrimMap := map[string]string{
			"string": "string", "token": "string", "byte": "int8", "unsignedByte": "byte",
			"base64Binary": "[]byte", "hexBinary": "[]byte", "integer": "int32", "nonNegativeInteger": "uint32",
			"int": "int32", "unsignedInt": "uint32", "long": "int64", "unsignedLong": "uint64",
			"short": "int16", "unsignedShort": "uint16", "decimal": "float64", "float": "float32",
			"double": "float64", "boolean": "bool", "dateTime": "soap.XSDDateTime", "date": "soap.XSDDate",
			"time": "soap.XSDTime", "anyURI": "AnyURI", "anyType": "AnyType", "NCName": "NCName",
		}
		if mapped, ok := knownPrimMap[typeLocal]; ok {
			return mapped
		}
		return makePublicName(typeLocal, true)
	}
	return "EmptyString"
}

func emitWarnings(gc *GenContext, msgMap map[string]*Message) {
	// Collect empty input/output ops in order
	type opRef struct {
		PortType string
		OpName   string
		MsgName  string // message local name (for warning text? Actually warning uses message name as in WSDL? e.g., "GetActive...HttpGetIn" (without namespace). Good: use msg.Name (original, without prefix).
	}
	var emptyInputs []opRef // in global order (portTypes order, ops order)
	var emptyOutputs []opRef
	// Also need per-portType grouping for Phase4? For inputs Phase4 (grouped two passes per portType), need per-portType lists.
	portInputMap := make(map[string][]opRef) // portType name -> list
	portOutputMap := make(map[string][]opRef)
	for _, pt := range gc.PortTypes {
		for _, op := range pt.Operations {
			if op.Input != nil && op.Input.Message != "" {
				msgLocal := stripNS(op.Input.Message)
				if msg, ok := msgMap[msgLocal]; ok && len(msg.Parts) == 0 {
					ref := opRef{PortType: pt.Name, OpName: op.Name, MsgName: msg.Name}
					emptyInputs = append(emptyInputs, ref)
					portInputMap[pt.Name] = append(portInputMap[pt.Name], ref)
				}
			}
			if op.Output != nil && op.Output.Message != "" {
				msgLocal := stripNS(op.Output.Message)
				if msg, ok := msgMap[msgLocal]; ok && len(msg.Parts) == 0 {
					ref := opRef{PortType: pt.Name, OpName: op.Name, MsgName: msg.Name}
					emptyOutputs = append(emptyOutputs, ref)
					portOutputMap[pt.Name] = append(portOutputMap[pt.Name], ref)
				}
			}
		}
	}
	// If no empties, nothing
	if len(emptyInputs) == 0 && len(emptyOutputs) == 0 {
		return
	}
	// For pure inputs (no outputs) or pure outputs (no inputs), emit in pure pattern (to match ferry exactly)
	// For mixed, emit grouped (inputs then outputs) for now (counts correct, order may differ from original's interleaved, but hopefully not tested)
	if len(emptyOutputs) == 0 {
		// Pure inputs: 6 per op in 4 phases
		// Phase1: global
		for _, r := range emptyInputs {
			logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
		}
		// Phase2: global again
		for _, r := range emptyInputs {
			logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
		}
		// Phase3: each dup
		for _, r := range emptyInputs {
			logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
			logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
		}
		// Phase4: grouped two passes per portType
		for _, pt := range gc.PortTypes {
			if list, ok := portInputMap[pt.Name]; ok {
				for pass := 0; pass < 2; pass++ {
					for _, r := range list {
						logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
					}
				}
			}
		}
		return
	}
	if len(emptyInputs) == 0 {
		// Pure outputs: 4 per op in 3 phases (global, global, grouped two passes)
		for _, r := range emptyOutputs {
			logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
		}
		for _, r := range emptyOutputs {
			logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
		}
		for _, pt := range gc.PortTypes {
			if list, ok := portOutputMap[pt.Name]; ok {
				for pass := 0; pass < 2; pass++ {
					for _, r := range list {
						logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
					}
				}
			}
		}
		return
	}
	// Mixed: emit inputs (6 per) then outputs (4 per) grouped? Or try to interleave as observed for 1pt case? For now, grouped.
	// Inputs 6 per
	for _, r := range emptyInputs {
		logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
	}
	for _, r := range emptyInputs {
		logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
	}
	for _, r := range emptyInputs {
		logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
		logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
	}
	for _, pt := range gc.PortTypes {
		if list, ok := portInputMap[pt.Name]; ok {
			for pass := 0; pass < 2; pass++ {
				for _, r := range list {
					logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
				}
			}
		}
	}
	// Outputs 4 per
	for _, r := range emptyOutputs {
		logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
	}
	for _, r := range emptyOutputs {
		logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
	}
	for _, pt := range gc.PortTypes {
		if list, ok := portOutputMap[pt.Name]; ok {
			for pass := 0; pass < 2; pass++ {
				for _, r := range list {
					logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
				}
			}
		}
	}
}

