				}
			}
		}
		return
	}
	if len(emptyInputs) == 0 {
		// Pure outputs: 4 per op in 3 phases (global, global, grouped two passes)
		for _, r := range emptyOutputs {
			logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
		}
		for _, r := range emptyOutputs {
			logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
		}
		for _, pt := range gc.PortTypes {
			if list, ok := portOutputMap[pt.Name]; ok {
				for pass := 0; pass < 2; pass++ {
					for _, r := range list {
						logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
					}
				}
			}
		}
		return
	}
	// Mixed: emit inputs (6 per) then outputs (4 per) grouped? Or try to interleave as observed for 1pt case? For now, grouped.
	// Inputs 6 per
	for _, r := range emptyInputs {
		logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
	}
	for _, r := range emptyInputs {
		logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
	}
	for _, r := range emptyInputs {
		logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
		logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
	}
	for _, pt := range gc.PortTypes {
		if list, ok := portInputMap[pt.Name]; ok {
			for pass := 0; pass < 2; pass++ {
				for _, r := range list {
					logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
				}
			}
		}
	}
	// Outputs 4 per
	for _, r := range emptyOutputs {
		logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
	}
	for _, r := range emptyOutputs {
		logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
	}
	for _, pt := range gc.PortTypes {
		if list, ok := portOutputMap[pt.Name]; ok {
			for pass := 0; pass < 2; pass++ {
				for _, r := range list {
					logWarn(r.MsgName + " message doesn't have any parts, ignoring message...")
				}
			}
		}
	}
}

