func resolveMessageFieldName(opMsg *OperationMessage, msgMap map[string]*Message) string {
	if opMsg == nil || opMsg.Message == "" {
		return "EmptyString"
	}
	msgLocal := stripNS(opMsg.Message)
	msg, ok := msgMap[msgLocal]
	if !ok || len(msg.Parts) == 0 {
		return "EmptyString"
	}
	part := msg.Parts[0]
	if part.Element != "" {
		elemLocal := stripNS(part.Element)
		return makePublicName(elemLocal, true)
	}
	if part.Type != "" {
		typeLocal := stripNS(part.Type)
		return makePublicName(typeLocal, true)
	}
	return "EmptyString"
}

